"use client";
import {ArtemisScope} from "./artemis-scope";
import View1 from "./components/performance-report/variants/02-comparison";
const views={"comparison":View1};
export interface ArtemisPerformanceReportProps {className?:string;variant?:"comparison";}
export function ArtemisPerformanceReport({className,variant="comparison"}:ArtemisPerformanceReportProps){const View=views[variant];return <ArtemisScope className={className}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { CalendarRange, CopyMinus, RotateCcwClock } from "lucide-react";
import { artemisCreatePortal } from "../../../artemis-scope";
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent as ReactKeyboardEvent } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { Calendar, SessionContext } from "./02-comparison/calendar";
import { ComparisonChart } from "./02-comparison/chart";
import { ChoiceMenu, type ChoiceOption } from "./02-comparison/compare-menu";
import { Roller } from "./02-comparison/roller";
import { Surface } from "./02-comparison/surface";
import { buildMetric, comparisonRange, formatChange, formatPeriod, INITIAL_RANGE, METRICS, type CompareMode, type MetricId, type Range, } from "./02-comparison/model";
const COMPARE_OPTIONS: readonly ChoiceOption<CompareMode>[] = [
    { value: "previous", label: "Previous period", icon: RotateCcwClock },
    { value: "year", label: "Year over year", icon: CalendarRange },
    { value: "none", label: "No comparison", icon: CopyMinus },
];
const COMPARE_NAME: Record<CompareMode, string> = {
    previous: "Previous period",
    year: "One year earlier",
    none: "",
};
const VS: Record<CompareMode, string> = { previous: "previous period", year: "one year earlier", none: "" };
const CARD_BASE = "art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:text-sm art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-w-0 art:flex-col art:gap-3 art:border art:bg-background art:p-4 art:text-left art:transition-colors art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring";
const TAB_BASE = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none";
const PRESS = { whileHover: { scale: 1.01 }, whileTap: { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS } as const;
const INDICATOR_SPRING = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 } as const;
function MetricIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chart-no-axes-combined art:size-3.5" aria-hidden="true">
      <path d="M12 16v5"/>
      <path d="M16 14.639V21"/>
      <path d="M20 10.656V21"/>
      <path d="m22 3-8.646 8.646a.5.5 0 0 1-.708 0L9.354 8.354a.5.5 0 0 0-.707 0L2 15"/>
      <path d="M4 18.463V21"/>
      <path d="M8 14.656V21"/>
    </svg>);
}
export default function PerformanceReportComparison() {
    const headingId = useId();
    const [range, setRange] = useState<Range>(INITIAL_RANGE);
    const [compare, setCompare] = useState<CompareMode>("previous");
    const [metric, setMetric] = useState<MetricId>("revenue");
    const [chartMode, setChartMode] = useState<"line" | "bars">("line");
    const onChartTabKey = (e: ReactKeyboardEvent<HTMLDivElement>) => {
        const modes = ["line", "bars"] as const;
        const tabs = Array.from(e.currentTarget.querySelectorAll<HTMLButtonElement>("[role=\"tab\"]"));
        const current = tabs.findIndex((t) => t === document.activeElement);
        if (current < 0)
            return;
        let next = current;
        if (e.key === "ArrowRight")
            next = (current + 1) % tabs.length;
        else if (e.key === "ArrowLeft")
            next = (current - 1 + tabs.length) % tabs.length;
        else if (e.key === "Home")
            next = 0;
        else if (e.key === "End")
            next = tabs.length - 1;
        else
            return;
        e.preventDefault();
        tabs[next]?.focus();
        const mode = modes[next];
        if (mode)
            setChartMode(mode);
    };
    const reduce = useReducedMotion();
    const pillId = useId();
    const [periodOpen, setPeriodOpen] = useState(false);
    const [resetOnClose, setResetOnClose] = useState(true);
    const periodBase = useId();
    const periodTriggerId = `${periodBase}-trigger`;
    const periodContentId = `${periodBase}-content`;
    const periodRootRef = useRef<HTMLDivElement>(null);
    const periodTriggerRef = useRef<HTMLButtonElement>(null);
    const periodValue = useMemo(() => ({ from: range.from, to: range.to }), [range]);
    const closePeriod = (resetDraft = true) => {
        setResetOnClose(resetDraft);
        setPeriodOpen(false);
        if (document.getElementById(periodContentId)?.contains(document.activeElement)) {
            periodTriggerRef.current?.focus({ preventScroll: true });
        }
    };
    useEffect(() => {
        if (!periodOpen)
            return;
        const onKey = (e: KeyboardEvent) => {
            if (e.key === "Escape")
                closePeriod();
        };
        const onDown = (e: PointerEvent) => {
            const t = e.target as Node;
            if (periodRootRef.current?.contains(t) || document.getElementById(periodContentId)?.contains(t))
                return;
            closePeriod();
        };
        window.addEventListener("keydown", onKey);
        window.addEventListener("pointerdown", onDown);
        return () => {
            window.removeEventListener("keydown", onKey);
            window.removeEventListener("pointerdown", onDown);
        };
    });
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    const views = useMemo(() => METRICS.map((spec) => buildMetric(spec, range, compare)), [range, compare]);
    const view = views.find((v) => v.spec.id === metric) ?? views[0];
    const period = formatPeriod(range.from, range.to);
    const cmpRange = comparisonRange(range, compare);
    const days = view.points.length;
    const change = view.change;
    const good = change !== null && (view.spec.higherIsBetter ? change > 0 : change < 0);
    const changeTone = change === null || change === 0 ? "art:text-muted-foreground" : good ? "art:text-success-foreground" : "art:text-destructive";
    return (<>
      <div className="art:w-full art:max-w-7xl art:overflow-x-clip">
        <section aria-labelledby={headingId} className="art:@container art:w-full art:min-w-0 art:space-y-5">
          <header className="art:flex art:flex-wrap art:items-end art:justify-between art:gap-4">
            <div>
              <h2 id={headingId} className="art:text-2xl art:font-normal art:tracking-tight art:text-muted-foreground">
                {"Period comparison"}
              </h2>
              <p className="art:mt-2 art:text-sm art:text-muted-foreground">
                {"See what changed, one period at a time."}
              </p>
            </div>
            <fieldset aria-label="Comparison filters" className="art:flex art:min-w-0 art:flex-wrap art:gap-2">
              <div ref={periodRootRef} className="art:relative art:inline-flex art:max-w-full">
                <button ref={periodTriggerRef} aria-label={`Current period: ${period}`} type="button" className="art:inline-flex art:h-10 art:w-fit art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background art:px-3 art:text-sm art:font-medium art:text-foreground art:transition-colors art:hover:bg-muted/40 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:disabled:opacity-40 art:max-w-full" id={periodTriggerId} aria-haspopup="dialog" aria-expanded={periodOpen} aria-controls={periodOpen ? periodContentId : undefined} onClick={() => { setResetOnClose(true); setPeriodOpen((o) => !o); }}>
                  <span className="art:inline-flex art:min-w-0 art:items-center art:gap-2">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-calendar-days art:size-4 art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                      <path d="M8 2v3"/>
                      <path d="M16 2v3"/>
                      <rect x="3" y="3" width="18" height="18" rx="2"/>
                      <path d="M3 9h18"/>
                      <path d="M8 13h.01"/>
                      <path d="M12 13h.01"/>
                      <path d="M16 13h.01"/>
                      <path d="M8 17h.01"/>
                      <path d="M12 17h.01"/>
                      <path d="M16 17h.01"/>
                    </svg>
                    <span className="art:truncate art:text-sm art:tabular-nums">{period}</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-down art:size-3.5 art:shrink-0 art:text-muted-foreground" aria-hidden="true">
                      <path d="m6 9 6 6 6-6"/>
                    </svg>
                  </span>
                </button>
                {mounted
            ? artemisCreatePortal(<SessionContext.Provider value={{ open: periodOpen, value: periodValue, resetOnClose }}>
                        <AnimatePresence>
                          {periodOpen ? (<Surface key="surface" triggerRef={periodTriggerRef} contentId={periodContentId} triggerId={periodTriggerId}>
                              <Calendar value={periodValue} onCancel={() => closePeriod(false)} onApply={(r) => {
                        setRange({ from: r.from, to: r.to });
                        closePeriod();
                    }}/>
                            </Surface>) : null}
                        </AnimatePresence>
                      </SessionContext.Provider>, document.body)
            : null}
              </div>
              <ChoiceMenu label="Compare with" value={compare} options={COMPARE_OPTIONS} onValueChange={setCompare}/>
            </fieldset>
          </header>
          <fieldset aria-label="Choose comparison metric" className="art:grid art:gap-3 art:@lg:grid-cols-2 art:@3xl:grid-cols-3">
            {views.map((v) => {
            const selected = v.spec.id === metric;
            return (<motion.button {...(!reduce ? PRESS : {})} key={v.spec.id} type="button" className={`${CARD_BASE} ${selected ? "art:border-primary/60" : "art:border-border art:hover:border-muted-foreground/50"} art:rounded-full`} aria-pressed={selected} tabIndex={0} onClick={() => setMetric(v.spec.id)}>
                  <span className="art:flex art:items-center art:justify-between art:gap-3 art:text-sm art:text-muted-foreground">
                    {v.spec.label}
                    <span className="art:grid art:size-7 art:place-items-center art:rounded-full art:bg-muted">
                      <MetricIcon />
                    </span>
                  </span>
                  {v.current === null ? (<span className="art:text-3xl art:font-medium">{"\u2014"}</span>) : (<Roller text={v.spec.format(v.current)} className="art:text-3xl art:font-medium art:tabular-nums art:tracking-tight"/>)}
                  <span className="art:flex art:flex-wrap art:items-center art:gap-x-2 art:gap-y-1 art:text-xs art:text-muted-foreground">
                    {v.change !== null ? (<>
                        <span>{formatChange(v.change)}</span>
                        <span>
                          {"vs."}
                          {" "}
                          {VS[compare]}
                        </span>
                      </>) : (<span>{compare === "none" ? v.spec.summary : "Comparison unavailable"}</span>)}
                  </span>
                </motion.button>);
        })}
          </fieldset>
          <div className="art:min-w-0 art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
            <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-b art:border-border art:px-5 art:py-4">
              <div>
                <h3 className="art:text-base art:font-normal art:text-muted-foreground">
                  {view.spec.label}
                  {" over time"}
                </h3>
                <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                  {days}
                  {" days \u00B7"}
                  {" "}
                  {view.spec.summary}
                </p>
              </div>
              <div>
                <div role="tablist" className="art:inline-flex art:items-center art:gap-1 art:w-fit art:max-w-full art:flex-wrap art:rounded-full art:border art:border-border art:bg-background art:p-1" aria-label="Comparison chart style" onKeyDown={onChartTabKey}>
                  {(["line", "bars"] as const).map((m) => {
            const active = chartMode === m;
            return (<div key={m} className="art:relative">
                        {active ? (<motion.span layout="position" layoutId={pillId} className="art:absolute art:inset-0 art:rounded-full art:bg-muted" style={{ borderRadius: 9999 }} transition={reduce ? { duration: 0 } : INDICATOR_SPRING}/>) : null}
                        <button type="button" role="tab" aria-selected={active} className={`${TAB_BASE} ${active ? "art:text-foreground art:delay-100" : "art:text-muted-foreground art:delay-0 art:hover:text-foreground"} art:h-9 art:rounded-full art:px-3 art:py-0 art:text-xs art:@min-[640px]/artemis:text-sm`} tabIndex={active ? 0 : -1} onClick={() => setChartMode(m)}>
                          {m === "line" ? "Line" : "Bars"}
                        </button>
                      </div>);
        })}
                </div>
              </div>
            </div>
            <div className="art:grid art:@3xl:grid-cols-[minmax(0,1fr)_240px]">
              <div className="art:min-w-0 art:p-4 art:@min-[640px]/artemis:p-5">
                <div className="art:mb-5 art:flex art:flex-wrap art:gap-x-5 art:gap-y-2 art:text-xs art:text-muted-foreground">
                  <span className="art:inline-flex art:items-center art:gap-2">
                    <span aria-hidden="true" className="art:h-0.5 art:w-4 art:rounded-full art:bg-primary"/>
                    {"Current period"}
                  </span>
                  {compare !== "none" ? (<span className="art:inline-flex art:items-center art:gap-2">
                      <span aria-hidden="true" className="art:w-4 art:border-t art:border-dashed art:border-muted-foreground"/>
                      {COMPARE_NAME[compare]}
                    </span>) : null}
                </div>
                {view.currentCoverage === 0 ? (<output className="art:flex art:h-64 art:items-center art:justify-center art:text-sm art:text-muted-foreground art:@min-[640px]/artemis:h-72">
                    {"No observations in this period."}
                  </output>) : (<>

                <motion.figure key={`${metric}-${range.from}-${range.to}-${view.compared ? "compared" : "single"}-${chartMode}`} aria-label={`${view.spec.label} by day of period`} className="art:h-64 art:min-w-0 art:@min-[640px]/artemis:h-72" initial={reduce ? false : { opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} transition={reduce ? { duration: 0 } : { duration: 0.35, ease: ARTEMIS_EASE_OUT }}>
                  <ComparisonChart mode={chartMode} view={view}/>
                </motion.figure>
                <div className="art:sr-only">
                  <table>
                    <caption>
                      {view.spec.label}
                      {" daily comparison"}
                    </caption>
                    <thead>
                      <tr>
                        <th scope="col">{"Current date"}</th>
                        <th scope="col">{"Current value"}</th>
                        {compare !== "none" ? (<>
                            <th scope="col">{"Comparison date"}</th>
                            <th scope="col">{"Comparison value"}</th>
                          </>) : null}
                      </tr>
                    </thead>
                    <tbody>
                      {view.points.map((p) => (<tr key={p.date}>
                          <th scope="row">{p.date}</th>
                          <td>{p.current === null ? "No observation" : view.spec.format(p.current)}</td>
                          {p.compareDate !== undefined && p.previous !== undefined ? (<>
                              <td>{p.compareDate}</td>
                              <td>{p.previous === null ? "No observation" : view.spec.format(p.previous)}</td>
                            </>) : null}
                        </tr>))}
                    </tbody>
                  </table>
                </div>
                </>)}
              </div>
              <aside aria-label="Selected metric comparison" className="art:flex art:flex-col art:gap-5 art:border-t art:border-border art:p-5 art:@3xl:border-l art:@3xl:border-t-0">
                <div>
                  <p className="art:text-xs art:text-muted-foreground">{"Current period"}</p>
                  <p className="art:mt-1 art:text-xs art:text-muted-foreground">{period}</p>
                  <p className="art:mt-3 art:text-2xl art:font-medium art:tabular-nums">{view.current === null ? "\u2014" : view.spec.format(view.current)}</p>
                </div>
                {cmpRange ? (<>
                    <div>
                      <p className="art:text-xs art:text-muted-foreground">{COMPARE_NAME[compare]}</p>
                      <p className="art:mt-1 art:text-xs art:text-muted-foreground">{formatPeriod(cmpRange.from, cmpRange.to)}</p>
                      <p className="art:mt-3 art:text-2xl art:font-medium art:tabular-nums art:text-muted-foreground">{view.previous === null ? "\u2014" : view.spec.format(view.previous)}</p>
                    </div>
                    <div className="art:border-t art:border-border art:pt-4">
                      <p className="art:text-xs art:text-muted-foreground">{"Change"}</p>
                      {change === null ? (<p className="art:mt-2 art:text-sm art:text-muted-foreground">{"Not enough data to compare"}</p>) : (<p className={`art:mt-2 art:flex art:items-center art:gap-1 art:text-xl art:font-medium art:tabular-nums ${changeTone}`}>
                        {change < 0 ? (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-down-right art:size-4" aria-hidden="true">
                            <path d="m7 7 10 10"/>
                            <path d="M17 7v10H7"/>
                          </svg>) : (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                            <path d="M7 7h10v10"/>
                            <path d="M7 17 17 7"/>
                          </svg>)}
                        {formatChange(change)}
                      </p>)}
                    </div>
                  </>) : null}
              </aside>
            </div>
            <footer className="art:flex art:flex-wrap art:justify-between art:gap-2 art:border-t art:border-border art:px-5 art:py-3 art:text-xs art:text-muted-foreground">
              <span>{compare === "none" ? "Showing the selected period." : "Periods align by day, using equal day counts."}</span>
              <span>
                {"Coverage: "}
                {view.currentCoverage}
                {"/"}
                {days}
                {" days"}
                {compare !== "none" ? ` \u00B7 comparison ${view.previousCoverage}/${days}` : null}
              </span>
            </footer>
          </div>
          <p aria-live="polite" className="art:sr-only">
            {"Showing "}
            {view.spec.label}
            {", "}
            {period}
            {"."}
            {" "}
            {change !== null ? `Change ${formatChange(change)}.` : null}
          </p>
        </section>
        <p className="art:mt-4 art:text-xs art:text-muted-foreground">
          {"Sample workspace \u00B7 Daily observations through Sep 30, 2026"}
        </p>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { ArtemisRangeCalendar, type ArtemisDayRange } from "../../../../lib/range-calendar";
export { ArtemisCalendarSession as SessionContext, type ArtemisDayRange as DayRange } from "../../../../lib/range-calendar";
const presets = [{ "label": "Last 7 days", "value": { "from": "2026-09-24", "to": "2026-09-30" } }, { "label": "Last 28 days", "value": { "from": "2026-09-03", "to": "2026-09-30" } }, { "label": "This month", "value": { "from": "2026-09-01", "to": "2026-09-30" } }];
export function Calendar(props: {
    value: Required<ArtemisDayRange>;
    onChange?: (range: ArtemisDayRange) => void;
    onApply: (range: Required<ArtemisDayRange>) => void;
    onCancel: () => void;
}) { return <ArtemisRangeCalendar {...props} min="0000-01-01" presets={presets} clearable={false}/>; }

"use client";
// @zeus-internal
import { useId } from "react";
import { Area, Bar, CartesianGrid, ComposedChart, Line, ResponsiveContainer, Tooltip, XAxis, YAxis, } from "recharts";
import { dayTicks, longDay, type MetricView, type Point } from "./model";
const TICK = { fill: "var(--artemis-muted-foreground)", className: "art:text-xs" } as const;
function TooltipCard({ active, payload, view }: {
    active?: boolean;
    payload?: ReadonlyArray<{
        payload?: unknown;
    }>;
    view: MetricView;
}) {
    const point = payload?.[0]?.payload as Point | undefined;
    if (!active || !point)
        return null;
    return (<div className="art:rounded-xl art:border art:border-border art:bg-background art:p-3 art:text-xs">
      <p className="art:mb-2 art:font-medium">
        {"Day "}
        {point.index}
      </p>
      <p className="art:flex art:justify-between art:gap-5">
        <span className="art:text-muted-foreground">{longDay(point.date)}</span>
        <span className="art:tabular-nums">{point.current === null ? "No observation" : view.spec.format(point.current)}</span>
      </p>
      {point.compareDate !== undefined && point.previous !== undefined ? (<p className="art:mt-2 art:flex art:justify-between art:gap-5">
          <span className="art:text-muted-foreground">{longDay(point.compareDate)}</span>
          <span className="art:tabular-nums">{point.previous === null ? "No observation" : view.spec.format(point.previous)}</span>
        </p>) : null}
    </div>);
}
export function ComparisonChart({ mode, view }: {
    mode: "line" | "bars";
    view: MetricView;
}) {
    const gradientId = useId();
    const ticks = dayTicks(view.points.length);
    const compare = view.compared;
    const xAxis = (gap: number) => (<XAxis dataKey="day" ticks={ticks} tickLine={false} axisLine={false} tickMargin={12} interval="preserveStartEnd" minTickGap={gap} tick={TICK}/>);
    const yAxis = (<YAxis width={54} domain={[0, "auto"]} tickCount={4} tickLine={false} axisLine={false} tickMargin={2} tickFormatter={view.spec.axis} tick={TICK}/>);
    const tooltip = (cursor: {
        stroke: string;
        strokeDasharray: string;
    } | {
        fill: string;
        fillOpacity: number;
    }) => (<Tooltip cursor={cursor} content={(props) => <TooltipCard active={props.active} payload={props.payload} view={view}/>}/>);
    return (<ResponsiveContainer width="100%" height="100%" minWidth={0}>
      <ComposedChart data={view.points} margin={{ top: 8, right: 8, bottom: 0, left: 0 }} barGap={3} barCategoryGap="22%" maxBarSize={24} accessibilityLayer>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--artemis-primary)" stopOpacity={0.13}/>
            <stop offset="100%" stopColor="var(--artemis-primary)" stopOpacity={0}/>
          </linearGradient>
        </defs>
        <CartesianGrid vertical={false} stroke="var(--artemis-border)" strokeDasharray="3 5"/>
        {xAxis(32)}
        {yAxis}
        {mode === "bars" ? tooltip({ fill: "var(--artemis-muted)", fillOpacity: 0.4 }) : tooltip({ stroke: "var(--artemis-border)", strokeDasharray: "3 3" })}
        {mode === "bars" && compare ? <Bar isAnimationActive={false} dataKey="previous" fill="var(--artemis-muted-foreground)" fillOpacity={0.3} radius={[3, 3, 0, 0]}/> : null}
        {mode === "bars" ? <Bar isAnimationActive={false} dataKey="current" fill="var(--artemis-primary)" radius={[3, 3, 0, 0]}/> : null}
        {mode === "line" && compare ? (<Line type="linear" dataKey="previous" stroke="var(--artemis-muted-foreground)" strokeWidth={1.5} strokeDasharray="5 5" dot={false} isAnimationActive={false}/>) : null}
        {mode === "line" ? (<Area type="linear" dataKey="current" stroke="var(--artemis-primary)" strokeWidth={2} fill={`url(#${gradientId})`} dot={false} isAnimationActive={false}/>) : null}
      </ComposedChart>
    </ResponsiveContainer>);
