      })}</div>
      <div className="art:mt-3 art:flex art:justify-between art:gap-2 art:border-t art:border-border art:pt-3"><ArtemisButton variant="ghost" className="art:h-9 art:rounded-full art:px-4" onClick={onCancel}>Cancel</ArtemisButton><ArtemisButton disabled={!complete} className="art:h-9 art:rounded-full art:px-4" onClick={() => { if (draft.from && draft.to) onApply({ from: draft.from, to: draft.to }); }}>Apply range</ArtemisButton></div>
    </div>
    <p id={`${id}-help`} className="art:sr-only">Use arrow keys to navigate dates, Home and End for the week, Page Up and Page Down for months, Shift with Page Up or Page Down for years. Enter or Space selects a date. Use the month and year buttons to jump directly. In the month or year choices, use arrow keys to move and Escape to return.</p><p role="status" aria-live="polite" className="art:sr-only">{announcement}</p>
  </section>;
}

